import{_ as e,c as d,o,ae as c}from"./chunks/framework.CFeneB-q.js";const g=JSON.parse('{"title":"PC 端 · 提交规范","description":"","frontmatter":{},"headers":[],"relativePath":"pc/standards/commit-specification.md","filePath":"pc/standards/commit-specification.md","lastUpdated":1789438865000}'),a={name:"pc/standards/commit-specification.md"};function r(s,t,i,n,l,p){return o(),d("div",null,[...t[0]||(t[0]=[c('<h1 id="pc-端-·-提交规范" tabindex="-1">PC 端 · 提交规范 <a class="header-anchor" href="#pc-端-·-提交规范" aria-label="Permalink to &quot;PC 端 · 提交规范&quot;">​</a></h1><blockquote><p>与 <code>keystone-deliver-ui</code> 的 commitizen + commitlint 配置对齐（2026-09-16 核对）。</p></blockquote><h2 id="commit-message-格式" tabindex="-1">commit message 格式 <a class="header-anchor" href="#commit-message-格式" aria-label="Permalink to &quot;commit message 格式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;scope&gt;): &lt;subject&gt;</span></span></code></pre></div><ul><li><p><strong>type</strong>（枚举，与 <code>.cz-config.js</code> 一致）：</p><table tabindex="0"><thead><tr><th>type</th><th>含义</th></tr></thead><tbody><tr><td><code>feature</code></td><td>新功能</td></tr><tr><td><code>bug</code></td><td>测试反馈 bug 列表中的 bug 号</td></tr><tr><td><code>fix</code></td><td>缺陷修复</td></tr><tr><td><code>ui</code></td><td>界面 / 样式调整</td></tr><tr><td><code>docs</code></td><td>文档</td></tr><tr><td><code>style</code></td><td>代码格式（不影响逻辑）</td></tr><tr><td><code>perf</code></td><td>性能优化</td></tr><tr><td><code>refactor</code></td><td>重构（既非新增也非修复）</td></tr><tr><td><code>release</code></td><td>发布</td></tr><tr><td><code>deploy</code></td><td>部署相关</td></tr><tr><td><code>test</code></td><td>测试相关</td></tr><tr><td><code>chore</code></td><td>构建过程或辅助工具变动</td></tr><tr><td><code>revert</code></td><td>回滚</td></tr><tr><td><code>build</code></td><td>打包</td></tr><tr><td><code>merge</code></td><td>分支合并（仅 commitlint 允许，cz 菜单不出现）</td></tr></tbody></table></li><li><p><strong>scope 必填</strong>：commitlint 强规则 <code>scope-empty: never</code>——写模块 / 业务域，如 <code>qual_mgmt</code>、<code>cfg_center</code>、<code>http</code>；</p></li><li><p><strong>subject</strong>：≤72 字符（<code>subjectLimit: 72</code>），中文简述，不加句号；header 长度上限校验已关闭，但请自觉精简；</p></li><li><p><strong>body / footer</strong>：cz 交互默认跳过，一般不写。</p></li></ul><p>示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feature(qual_mgmt): 新增回弹仪试验页面</span></span>\n<span class="line"><span>bug(personnel_mgmt): 修复考勤记录分页重复</span></span>\n<span class="line"><span>chore(env): 切换 pzgc 生产 API 地址</span></span></code></pre></div><h2 id="交互式提交-pnpm-commit" tabindex="-1">交互式提交：<code>pnpm commit</code> <a class="header-anchor" href="#交互式提交-pnpm-commit" aria-label="Permalink to &quot;交互式提交：`pnpm commit`&quot;">​</a></h2><p>项目接入 commitizen（cz-customizable）。<strong>推荐一律用 <code>pnpm commit</code> 代替 <code>git commit</code></strong>，按提示选 type、填 scope、写 subject，生成符合上述格式的 message。</p><div class="warning custom-block"><p class="custom-block-title">强制现状（如实记录）</p><p>husky 当前<strong>只挂了 pre-commit（lint-staged），没有 commit-msg 钩子</strong>——commitlint 规则不会在提交时自动拦截，靠 <code>pnpm commit</code> 流程 + MR 评审保证。直接 <code>git commit -m &quot;xxx&quot;</code> 不会被拦，但会过不了评审。</p></div><h2 id="分支命名规范" tabindex="-1">分支命名规范 <a class="header-anchor" href="#分支命名规范" aria-label="Permalink to &quot;分支命名规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分支</th><th>说明</th></tr></thead><tbody><tr><td><code>master</code></td><td>生产环境分支，用于发布正式环境的代码，已锁，不可随意修改</td></tr><tr><td><code>stable</code></td><td>预发布分支，用于发布开发/测试环境的代码，已锁，不可随意修改</td></tr><tr><td><code>dev/功能名称</code></td><td>常规开发分支</td></tr><tr><td><code>hotfix/bug名称</code></td><td>紧急 bug 修复，需要立刻合到 master 分支验证</td></tr><tr><td><code>fix/bug名称</code></td><td>一般 bug 修复，如 <code>fix/#709-712</code></td></tr><tr><td><code>feat/功能名称</code></td><td>功能模块新增，用于新功能开发，时间要求较缓</td></tr><tr><td><code>refactor/功能名称</code></td><td>功能模块重构</td></tr><tr><td><code>perf/优化内容</code></td><td>用于性能优化</td></tr></tbody></table><h2 id="mr-评审与发布流" tabindex="-1">MR 评审与发布流 <a class="header-anchor" href="#mr-评审与发布流" aria-label="Permalink to &quot;MR 评审与发布流&quot;">​</a></h2><ol><li><strong>日常流转</strong>：<code>dev/* / feat/* / fix/*</code> → 提 MR → 评审通过 → 合入 <code>stable</code> → 随 <code>stable</code> 发布到开发/测试环境验证；</li><li><strong>发布生产</strong>：<code>stable</code> 验证通过后合入 <code>master</code> 发布正式环境；</li><li><strong>紧急修复</strong>：<code>hotfix/*</code> 从 <code>master</code> 拉出，修复后合回 <code>master</code> 验证，再同步 <code>stable</code>；</li><li><strong>纪律</strong>：基于 dev 的分支保持独立干净，一个分支只做一类事；每天先更新远端代码再开发。</li></ol>',14)])])}const h=e(a,[["render",r]]);export{g as __pageData,h as default};
